INSERT INTO tutor_reviews (id, student_id, tutor_id, rating, comment, created_at, updated_at) VALUES (1, 22, 21, 5, 'Thầy dạy rất tận tình và dễ hiểu. Nhờ thầy mà môn Toán của em tiến bộ rõ rệt!', NOW() - INTERVAL '29 days', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO tutor_reviews (id, student_id, tutor_id, rating, comment, created_at, updated_at) VALUES (2, 23, 21, 5, 'Phương pháp giải toán hình học không gian của thầy cực kỳ trực quan và dễ nhớ.', NOW() - INTERVAL '28 days', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO tutor_reviews (id, student_id, tutor_id, rating, comment, created_at, updated_at) VALUES (3, 24, 21, 4, 'Thầy giảng bài kỹ, bài tập luyện tập đa dạng bám sát đề thi THPTQG.', NOW() - INTERVAL '27 days', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO tutor_reviews (id, student_id, tutor_id, rating, comment, created_at, updated_at) VALUES (4, 33, 21, 5, 'Gia sư tuyệt vời, giải thích chi tiết các dạng bài khó và luôn kiên nhẫn.', NOW() - INTERVAL '26 days', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO tutor_reviews (id, student_id, tutor_id, rating, comment, created_at, updated_at) VALUES (5, 34, 21, 5, 'Em đã tự tin hơn rất nhiều khi làm đề thi thử tốt nghiệp. Cảm ơn thầy!', NOW() - INTERVAL '25 days', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO tutor_reviews (id, student_id, tutor_id, rating, comment, created_at, updated_at) VALUES (6, 22, 25, 5, 'Cô dạy môn Vật Lý rất hay, có nhiều ví dụ thực tế giúp em dễ hình dung.', NOW() - INTERVAL '24 days', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO tutor_reviews (id, student_id, tutor_id, rating, comment, created_at, updated_at) VALUES (7, 23, 25, 5, 'Bài giảng về phần Dao động cơ rất chi tiết, mẹo bấm máy tính Casio siêu nhanh.', NOW() - INTERVAL '23 days', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO tutor_reviews (id, student_id, tutor_id, rating, comment, created_at, updated_at) VALUES (8, 24, 25, 4, 'Cô giảng dễ hiểu, hỗ trợ giải đáp thắc mắc ngoài giờ rất nhiệt tình.', NOW() - INTERVAL '22 days', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO tutor_reviews (id, student_id, tutor_id, rating, comment, created_at, updated_at) VALUES (9, 33, 25, 5, 'Điểm kiểm tra 1 tiết môn Lý của em đã tăng từ 6.5 lên 8.5.', NOW() - INTERVAL '21 days', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO tutor_reviews (id, student_id, tutor_id, rating, comment, created_at, updated_at) VALUES (10, 35, 25, 5, 'Gia sư có chuyên môn sâu, phong cách dạy lôi cuốn và đúng giờ.', NOW() - INTERVAL '20 days', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO tutor_reviews (id, student_id, tutor_id, rating, comment, created_at, updated_at) VALUES (11, 22, 26, 5, 'Thầy dạy môn Hóa học rất logic, sơ đồ tư duy phản ứng hữu cơ rất bổ ích.', NOW() - INTERVAL '19 days', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO tutor_reviews (id, student_id, tutor_id, rating, comment, created_at, updated_at) VALUES (12, 23, 26, 4, 'Bài giảng sinh động, nhiều câu hỏi trắc nghiệm hay.', NOW() - INTERVAL '18 days', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO tutor_reviews (id, student_id, tutor_id, rating, comment, created_at, updated_at) VALUES (13, 24, 26, 5, 'Nhờ thầy mà em không còn sợ phần Hóa hữu cơ nữa.', NOW() - INTERVAL '17 days', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO tutor_reviews (id, student_id, tutor_id, rating, comment, created_at, updated_at) VALUES (14, 34, 26, 5, 'Thầy kèm rất sát sao, nhắc nhở làm bài tập về nhà chu đáo.', NOW() - INTERVAL '16 days', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO tutor_reviews (id, student_id, tutor_id, rating, comment, created_at, updated_at) VALUES (15, 35, 26, 5, '10/10 cho sự nhiệt huyết của thầy Đỗ Thu Hà.', NOW() - INTERVAL '15 days', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO tutor_reviews (id, student_id, tutor_id, rating, comment, created_at, updated_at) VALUES (16, 22, 27, 5, 'Cô dạy Tiếng Anh phát âm chuẩn, bài tập ngữ pháp chắc chắn.', NOW() - INTERVAL '14 days', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO tutor_reviews (id, student_id, tutor_id, rating, comment, created_at, updated_at) VALUES (17, 23, 27, 5, 'Phần Reading và Vocab cô cung cấp rất sát với kỳ thi đại học.', NOW() - INTERVAL '13 days', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO tutor_reviews (id, student_id, tutor_id, rating, comment, created_at, updated_at) VALUES (18, 24, 27, 4, 'Cách dạy trẻ trung, tạo không khí học tập thoải mái.', NOW() - INTERVAL '12 days', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO tutor_reviews (id, student_id, tutor_id, rating, comment, created_at, updated_at) VALUES (19, 33, 27, 5, 'Cô sửa bài luận chi tiết từng lỗi dùng từ và ngữ pháp.', NOW() - INTERVAL '11 days', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO tutor_reviews (id, student_id, tutor_id, rating, comment, created_at, updated_at) VALUES (20, 35, 27, 5, 'Em đã tự tin giao tiếp và làm tốt các bài đọc hiểu tiếng Anh.', NOW() - INTERVAL '10 days', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO tutor_reviews (id, student_id, tutor_id, rating, comment, created_at, updated_at) VALUES (21, 22, 28, 5, 'Thầy dạy môn Toán tư duy tốt, luôn khuyến khích học sinh tự suy nghĩ.', NOW() - INTERVAL '9 days', NOW()) ON CONFLICT DO NOTHING;
